package in.aicon.pocket;
import android.app.*;import android.content.*;import android.database.sqlite.*;import android.telephony.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
/** All SMS APIs in this suite are Robolectric shadows. No phone or carrier is used. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class AutoSmsTest {
 Context c;SQLiteDatabase db;String key="test-plan",contact="test-contact",uuid="11111111-1111-4111-8111-111111111111";JSONObject plan;
 org.robolectric.shadows.ShadowSmsManager sms(){return Shadows.shadowOf(c.getSystemService(SmsManager.class).createForSubscriptionId(1));}
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.getSharedPreferences("hisab-account-directory",0).edit().clear().commit();DuePlans.prefs(c).edit().clear().commit();Shadows.shadowOf((Application)c).grantPermissions(android.Manifest.permission.SEND_SMS);org.robolectric.shadows.ShadowSubscriptionManager.setDefaultSmsSubscriptionId(1);c.deleteDatabase("pocket.db");db=c.openOrCreateDatabase("pocket.db",0,null);db.execSQL("CREATE TABLE tx(uuid TEXT,kind TEXT,person TEXT,amount INTEGER,loan TEXT)");db.execSQL("INSERT INTO tx VALUES(?,'lent','Sample',8000,'')",new Object[]{uuid});ContactLinks.save(c,contact,"Sample","+919000000001");plan=new JSONObject().put("autoSms",true).put("phone","+919000000001").put("contactKey",contact).put("database","pocket.db").put("uuid",uuid).put("maximum",8000).put("kind","lent").put("person","Sample").put("currency","INR").put("date","2026-11-15").put("sim",1).put("subject","");DuePlans.prefs(c).edit().putString(key,plan.toString()).commit();sms().clearLastSentTextMessageParams();}
 @After public void close(){db.close();}
 @Test public void unchangedExplicitPlanAttemptsOnceInSimulation()throws Exception{AutoSms.run(c,key,plan);assertNotNull(sms().getLastSentTextMessageParams());assertFalse(DuePlans.get(c,key).optBoolean("autoSms"));sms().clearLastSentTextMessageParams();AutoSms.run(c,key,DuePlans.get(c,key));assertNull(sms().getLastSentTextMessageParams());}
 @Test public void changedContactNeverSends()throws Exception{ContactLinks.save(c,contact,"Sample","+919000000002");AutoSms.run(c,key,plan);assertNull(sms().getLastSentTextMessageParams());assertFalse(DuePlans.get(c,key).optBoolean("autoSms"));}
 @Test public void changedSimNeverSends(){org.robolectric.shadows.ShadowSubscriptionManager.setDefaultSmsSubscriptionId(2);AutoSms.run(c,key,plan);assertNull(sms().getLastSentTextMessageParams());}
 @Test public void settledOrIncreasedDebtNeverSends(){db.execSQL("UPDATE tx SET amount=0");AutoSms.run(c,key,plan);assertNull(sms().getLastSentTextMessageParams());try{plan.put("autoSms",true);}catch(Exception e){throw new RuntimeException(e);}db.execSQL("UPDATE tx SET amount=9000");AutoSms.run(c,key,plan);assertNull(sms().getLastSentTextMessageParams());}
 @Test public void attemptCallbackCannotRewriteChangedPlan()throws Exception{plan.put("attempt","new").put("smsStatus","fresh");DuePlans.prefs(c).edit().putString(key,plan.toString()).commit();new SmsResultReceiver().onReceive(c,new Intent("in.aicon.pocket.SMS_RESULT").putExtra("key",key).putExtra("attempt","old"));assertEquals("fresh",DuePlans.get(c,key).optString("smsStatus"));}
}
